// Generates src/icon-data.js from the SVGs in src/icons (style1), src/icons2
// (style2) and src/icons3 (style3), so the card ships its animated icons inside the bundle
// and needs no network or extra files to show them. Run with `npm run icons`;
// the unit tests fail when the generated file is out of date.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';

const root = new URL('../', import.meta.url);

export function generateIconModule() {
  const styles = { style1: 'src/icons/', style2: 'src/icons2/', style3: 'src/icons3/' };
  const lines = [
    '// Generated by scripts/build-icons.mjs from src/icons, src/icons2 and src/icons3. Do not edit.',
    '// style1 and style2: Bas Milius, https://github.com/basmilius/weather-icons (MIT).',
    '// style3: amCharts, https://www.amcharts.com/free-animated-svg-weather-icons/ (CC BY 4.0).',
    'export default {',
  ];
  for (const [style, dir] of Object.entries(styles)) {
    lines.push(`  ${style}: {`);
    for (const file of readdirSync(new URL(dir, root)).filter((f) => f.endsWith('.svg')).sort()) {
      const svg = readFileSync(new URL(dir + file, root), 'utf8').trim();
      lines.push(`    ${JSON.stringify(file.slice(0, -4))}: ${JSON.stringify(svg)},`);
    }
    lines.push('  },');
  }
  lines.push('};', '');
  return lines.join('\n');
}

if (import.meta.url === `file://${process.argv[1]}`) {
  writeFileSync(new URL('src/icon-data.js', root), generateIconModule());
}
